window.AUTH=window.AUTH||{};window.AUTH["18-6662"]={"d":"18-6662","id":"2019/18-6662","n":"Shular v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Eddie Shular","date":"2019-09-25","url":"https://www.supremecourt.gov/DocketPDF/18/18-6662/117045/20190925150711706_18-6662ts.pdf","side":"pet","n":55},{"k":"respondent","label":"Brief of respondent United States","date":"2019-11-22","url":"https://www.supremecourt.gov/DocketPDF/18/18-6662/123445/20191122160200867_18-6662bsUnitedStates.pdf","side":"res","n":50},{"k":"reply","label":"Reply of petitioner Eddie Shular","date":"2019-12-20","url":"https://www.supremecourt.gov/DocketPDF/18/18-6662/126343/20191220124744751_18-6662rb.pdf","side":"pet","n":28}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/589US2PP_final.pdf#page=46","tr":true,"items":[{"t":"case","label":"Begay v. United States","cite":"553 U.S. 137","y":2008,"id":"2007/06-11543","sc":1,"ar":1,"sum":"In a 6-3 vote, the Court held that Begay's DWI convictions did not qualify as \"violent felonies\" because they were too different from the violent felony examples provided by Congress in the Armed Career Criminal Act (such as burglary, arson and extortion). Therefore, Begay should not have been subject to the mandatory sentencing hike.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Chambers v. United States","cite":"555 U.S. 122","y":2009,"id":"2008/06-11206","sc":1,"op":1,"sum":"The Court found that the \"failure to report\" crime does not satisfy the Armed Career Criminals Act's (ACCA) \"crime of violence\" definition.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Chicone v. State","cite":"684 So. 2d 736","y":1996,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%202d/684/736/","ar":1,"sum":"Holding that knowledge of the illicit nature of the substance was an element of Florida’s controlled substance offenses, rejecting the State’s argument that such knowledge was an affirmative defense.","sumSrc":"brief:0","by":{"0":"22","1":"7, 27","2":"14"}},{"t":"case","label":"Dawkins v. State","cite":"547 A.2d 1041","y":1988,"court":"Md.","url":"https://www.courtlistener.com/c/A.2d/547/1041/","by":{"0":"22"}},{"t":"case","label":"Descamps v. United States","cite":"570 U.S. 254","y":2013,"id":"2012/11-9540","sc":1,"sum":"The Court held that it was improper to apply the categorical approach in which the courts apply elements of a prior conviction with elements of a generic crime in order to enhance a sentence under the ACCA.","sumSrc":"Oyez","by":{"0":"5, 8","1":"17","2":"8"}},{"t":"case","label":"Erlengbaugh v. United States","cite":"409 U.S. 239","y":1972,"id":"1972/71-839","sc":1,"sum":"Causing a publication to be carried by a facility of interstate commerce with an intent to facilitate the operation of an illegal gambling business is a violation of 18 U. S. C. § 1952. The exception for \"any newspaper or similar publication\" contained in 18 U. S. C. § 1953, which prohibits the interstate shipment of certain gambling paraphernalia, was not intended to be read into § 1952. Pp. 242-248. 452 F. 2d 967, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Esquivel-Quintana v. Sessions","cite":"137 S. Ct. 1562","y":2017,"id":"2016/16-54","sc":1,"op":1,"ar":1,"sum":"The Court determined that the crime of “unlawful sexual intercourse with a minor” as defined by California law cannot be categorically considered the aggravated felony of “sexual abuse of a minor” for the purpose of mandatory removal under the Immigration and Nationality Act (INA).","sumSrc":"Oyez","by":{"0":"8"}},{"t":"case","label":"Gonzales v. Oregon","cite":"546 U.S. 243","y":2006,"id":"2005/04-623","sc":1,"sum":"The Court decided that the Controlled Substance Act did not ban the use of controlled substances in physician-assisted suicide, nor does the Attorney General have the power to determine what is a violation of the Act.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"case","label":"Gustafson v. Alloyd Co., Inc.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"sum":"Petitioners (collectively Gustafson), the sole shareholders of Alloyd, Inc., sold substantially all of its stock to respondents and other buyers in a private sale agreement. The purchase price included a payment reflecting an estimated increase in the company's net worth from the end of the previous year through the closing, since hard financial data were unavailable. The contract provided that if a year-end audit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"James v. United States","cite":"550 U.S. 192","y":2007,"id":"2006/05-9264","sc":1,"sum":"The Court ruled 5-3 that attempted burglary is a \"violent felony\" for purposes of the Armed Career Criminal Act.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Johnson v. United States","cite":"135 S. Ct. 2551","y":2015,"id":"2014/13-7120","sc":1,"sum":"The Court determined that the residual clause of the Armed Criminal Career Act is unconstitutionally vague.","sumSrc":"Oyez","by":{"0":"8, 27","1":"17"}},{"t":"case","label":"Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"ar":1,"sum":"The Court held that state DUI offenses, except when involving purposeful intent, are accidental and not crimes of violence under federal law. Le therefore did not commit an aggravated felony for which he could be deported.","sumSrc":"Oyez","by":{"0":"23","2":"2, 9, 15"}},{"t":"case","label":"Lockhart v. United States","cite":"136 S. Ct. 958","y":2016,"id":"2015/14-8358","sc":1,"sum":"The Court determined that a prior conviction of “aggravated sexual abuse” or “sexual abuse” may trigger a mandatory minimum sentence, even when the prior conviction did not involve a minor.","sumSrc":"Oyez","by":{"0":"16, 29","2":"14"}},{"t":"case","label":"McFadden v. United States","cite":"135 S. Ct. 2298","y":2015,"id":"2014/14-378","sc":1,"ar":1,"sum":"The Court decided that in order to fulfill the intent element of The Controlled Substance Analogue Enforcement Act of 1986, a person must either know that the substance is a controlled substance or be aware of what the substance is without knowing that it is controlled.","sumSrc":"Oyez","by":{"0":"22, 24","2":"5"}},{"t":"case","label":"Mellouli v. Lynch","cite":"135 S. Ct. 1980","y":2015,"id":"2014/13-1034","sc":1,"sum":"The Government must prove the connection between a state drug paraphernalia conviction and a substance listed in the Controlled Substances Act to trigger deportability under the Immigration and Nationality Act.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Moncrieffe v. Holder","cite":"569 U.S. 184","y":2013,"id":"2012/11-702","sc":1,"ar":1,"sum":"The Court found that distribution of small amounts of marijuana does not constitute an aggravated felony and thus, does not require deportation of the distributor.","sumSrc":"Oyez","by":{"0":"5, 14","2":"9"}},{"t":"case","label":"Quarles v. United States","cite":"139 S. Ct. 1872","y":2019,"id":"2018/17-778","sc":1,"sum":"Michigan’s third-degree home-invasion statute substantially corresponds to or is narrower than generic burglary for purposes of qualifying for enhanced sentencing under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"7, 22","1":"26, 27, 29, 30","2":"16"}},{"t":"case","label":"Rehaif v. United States","cite":"139 S. Ct. 2191","y":2019,"id":"2018/17-9560","sc":1,"sum":"In a prosecution under 18 U. S. C. §922(g) and §924(a)(2), the Government must prove both that the defendant knew he possessed a firearm and that he knew he belonged to the relevant category of persons barred from possessing a firearm.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"7, 23","2":"10, 17"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18","1":"15, 16"}},{"t":"case","label":"Scheidler v. Nat’l Org. for Women, Inc.","cite":"537 U.S. 393","y":2003,"id":"2002/01-1118","sc":1,"op":1,"ar":1,"sum":"The Court held that abortion opponents did not commit extortion because they did not \"obtain\" property from the abortion supporters as required by the Hobbs Act. The Court further held that is first holding renders insufficient the other bases or predicate acts of racketeering supporting the jury's conclusion that the abortion opponents violated RICO.","sumSrc":"Oyez","by":{"0":"5, 15","1":"24, 25","2":"1, 4"}},{"t":"case","label":"Sessions v. Dimaya","cite":"138 S. Ct. 1204","y":2018,"id":"2017/15-1498","sc":1,"sum":"A case in which the Court struck down the Immigration and Nationality Act’s “crime of violence” provision as unconstitutionally vague in violation of the Due Process Clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"0":"27, 28","1":"19"}},{"t":"case","label":"Staples v. United States","cite":"511 U.S. 600","y":1994,"id":"1993/92-1441","sc":1,"op":1,"sum":"To obtain a § 5861(d) conviction, the Government should have been required to prove beyond a reasonable doubt that Staples knew that his rifle had the characteristics that brought it within the statutory definition of a machinegun.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7, 23"}},{"t":"case","label":"State v. Dominguez","cite":"509 So. 2d 917","y":1987,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%202d/509/917/","sum":"Holding that knowledge of the illicit nature of the substance was an element of Florida’s controlled substance offenses, rejecting the State’s argument that such knowledge was an affirmative defense.","sumSrc":"brief:0","by":{"0":"22"}},{"t":"case","label":"Sykes v. United States","cite":"564 U.S. 1","y":2011,"id":"2010/09-11311","sc":1,"sum":"The Court held that a conviction for resisting arrest counts as a violent felony under the Armed Career Criminal Act.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"op":3,"sum":"An offense constitutes \"burglary\" under §924(e) if, regardless of its exact definition or label, it has the basic elements of a \"generic\" burglary-i. e., an unlawful or unprivileged entry into, or remaining in, a building or other structure, with intent to commit a crime-or if the charging paper and jury instructions actually required the jury to find all the elements of generic burglary in order to convict the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"7, 8, 14, 17"}},{"t":"case","label":"United States v. Alaska","cite":"521 U.S. 1","y":1997,"id":"1996/84_orig","sc":1,"sum":"The Court ruled that the federal government, the United States, owned the disputed submerged lands - adjacent to the National Wildlife Refuge and the National Petroleum Reserve - along Alaska's Arctic Coast.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"United States v. Brandon","cite":"247 F.3d 186","y":2001,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/247/186/","by":{"0":"28, 29"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"passim"}},{"t":"case","label":"United States v. Eason","cite":"919 F.3d 385","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/919/385/","by":{"0":"25, 26"}},{"t":"case","label":"United States v. Gibbs","cite":"656 F.3d 180","y":2011,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/656/180/","by":{"0":"27"}},{"t":"case","label":"United States v. Hayes","cite":"555 U.S. 415","y":2009,"id":"2008/07-608","sc":1,"op":2,"sum":"With Justice Ruth Bader Ginsburg writing for the majority and joined by Justice John Paul Stevens, Justice Anthony M. Kennedy, Justice David H. Souter, Justice Stephen G. Breyer, and Justice Samuel A. Alito, and joined in part by Justice Clarence Thomas, the Court reasoned that the language of the Gun Control Act suggested that the predicate offense statute need only include \"the use of force\" as an element of the crime and need not include a \"domestic relationship\" as an additional element.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"United States v. Mulkern","cite":"854 F.3d 87","y":2016,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/854/87/","by":{"0":"29"}},{"t":"case","label":"United States v. Stitt","cite":"139 S. Ct. 399","y":2018,"id":"2018/17-765","sc":1,"sum":"The term “burglary” in the Armed Career Criminal Act includes burglary of a structure or vehicle that has been adapted or is customarily used for overnight accommodation.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"7, 22","1":"17, 26, 27, 29, 30","2":"8, 16"}},{"t":"case","label":"United States v. White","cite":"837 F.3d 1225","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/837/1225/","by":{"0":"8, 24, 25, 28","1":"20, 22"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(a)(2)","(e)(1)","(e)(2)","(e)(2)(A)(ii)","(e)(2)(B)(i)","(e)(2)(B)(ii)","(e)","(e)(2)(A)","(e)(2)(A)(i)(1988)","(e)(2)(A)(i)","(e)(2)(B)","(a)(1)","(c)(2)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"0":"3, 3, 16, passim, 17, 14, 17","1":"4, 4, 4, 5, 5, 4, 4, 4, 2, 2, 2, 3, 15, 15","2":"6, 5, 3, 5, 6, 17, 6"}},{"t":"usc","label":"18 U.S.C. § 1961","url":"https://www.law.cornell.edu/uscode/text/18/1961","subs":["(1)(A)"],"stext":{"head":"§1961. Definitions","paras":[[0,"As used in this chapter—"],[1,"(1) \"racketeering activity\" means (A) any act or threat involving murder, kidnapping, gambling, arson, robbery, bribery, extortion, dealing in obscene matter, or dealing in a controlled substance or listed chemical (as defined in section 102 of the Controlled Substances Act), which is chargeable under State law and punishable by imprisonment for more than one year; (B) any act which is indictable under any of the following provisions of title 18, United States Code: Section 201 (relating to bribery), section 224 (relating to sports bribery), sections 471, 472, and 473 (relating to counterfeiting), section 659 (relating to theft from interstate shipment) if the act indictable under section 659 is felonious, section 664 (relating to embezzlement from pension and welfare funds), sections 891–894 (relating to extortionate credit transactions), section 932 (relating to straw purchasing), section 933 (relating to trafficking in firearms), section 1028 (relating to fraud and related activity in connection with identification documents), section 1029 (relating to fraud and related activity in connection with access devices), section 1084 (relating to the transmission of gambling information), section 1341 (relating to mail fraud), section 1343 (relating to wire fraud), section 1344 (relating to financial institution fraud), section 1351 (relating to fraud in foreign labor contracting), section 1425 (relating to the procurement of citizenship or nationalization unlawfully), section 1426 (relating to the reproduction of naturalization or citizenship papers), section 1427 (relating to the sale of naturalization or citizenship papers), sections 1461–1465 (relating to obscene matter), section 1503 (relating to obstruction of justice), section 1510 (relating to obstruction of criminal investigations), section 1511 (relating to the obstruction of State or local law enforcement), section 1512 (relating to tampering with a witness, victim, or an informant), section 1513 (relating to retaliating against a witness, victim, or an informant), section 1542 (relating to false statement in application and use of passport), section 1543 (relating to forgery or false use of passport), section 1544 (relating to misuse of passport), section 1546 (relating to fraud and misuse of visas, permits, and other documents), sections 1581–1592 (relating to peonage, slavery, and trafficking in persons).,1 sections 1831 and 1832 (relating to economic espionage and theft of trade secrets), section 1951 (relating to interference with commerce, robbery, or extortion), section 1952 (relating to racketeering), section 1953 (relating to interstate transportation of wagering paraphernalia), section 1954 (relating to unlawful welfare fund payments), section 1955 (relating to the prohibition of illegal gambling businesses), section 1956 (relating to the laundering of monetary instruments), section 1957 (relating to engaging in monetary transactions in property derived from specified unlawful activity), section 1958 (relating to use of interstate commerce facilities in the commission of murder-for-hire), section 1960 (relating to illegal money transmitters), sections 2251, 2251A, 2252, and 2260 (relating to sexual exploitation of children), sections 2312 and 2313 (relating to interstate transportation of stolen motor vehicles), sections 2314 and 2315 (relating to interstate transportation of stolen property), section 2318 (relating to trafficking in counterfeit labels for phonorecords, computer programs or computer program documentation or packaging and copies of motion pictures or other audiovisual works), section 2319 (relating to criminal infringement of a copyright), section 2319A (relating to unauthorized fixation of and trafficking in sound recordings and music videos of live musical performances), section 2320 (relating to trafficking in goods or services bearing counterfeit marks), section 2321 (relating to trafficking in certain motor vehicles or motor vehicle parts), sections 2341–2346 (relating to trafficking in contraband cigarettes), sections 2421–24 (relating to white slave traffic),2 sections 175–178 (relating to biological weapons), sections 229–229F (relating to chemical weapons), section 831 (relating to nuclear materials), (C) any act which is indictable under title 29, United States Code, section 186 (dealing with restrictions on payments and loans to labor organizations) or section 501(c) (relating to embezzlement from union funds), (D) any offense involving fraud connected with a case under title 11 (except a case under section 157 of this title), fraud in the sale of securities, or the felonious manufacture, importation, receiving, concealment, buying, selling, or otherwise dealing in a controlled substance or listed chemical (as defined in section 102 of the Controlled Substances Act), punishable under any law of the United States, (E) any act which is indictable under the Currency and Foreign Transactions Reporting Act, (F) any act which is indictable under the Immigration and Nationality Act, section 274 (relating to bringing in and harboring certain aliens), section 277 (relating to aiding or assisting certain aliens to enter the United States), or section 278 (relating to importation of alien for immoral purpose) if the act indictable under such section of such Act was committed for the purpose of financial gain, or (G) any act that is indictable under any provision listed in section 2332b(g)(5)(B);"],[1,"(2) \"State\" means any State of the United States, the District of Columbia, the Commonwealth of Puerto Rico, any territory or possession of the United States, any political subdivision, or any department, agency, or instrumentality thereof;"],[1,"(3) \"person\" includes any individual or entity capable of holding a legal or beneficial interest in property;"],[1,"(4) \"enterprise\" includes any individual, partnership, corporation, association, or other legal entity, and any union or group of individuals associated in fact although not a legal entity;"],[1,"(5) \"pattern of racketeering activity\" requires at least two acts of racketeering activity, one of which occurred after the effective date of this chapter and the last of which occurred within ten years (excluding any period of imprisonment) after the commission of a prior act of racketeering activity;"],[1,"(6) \"unlawful debt\" means a debt (A) incurred or contracted in gambling activity which was in violation of the law of the United States, a State or political subdivision thereof, or which is unenforceable under State or Federal law in whole or in part as to principal or interest because of the laws relating to usury, and (B) which was incurred in connection with the business of gambling in violation of the law of the United States, a State or political subdivision thereof, or the business of lending money or a thing of value at a rate usurious under State or Federal law, where the usurious rate is at least twice the enforceable rate;"],[1,"(7) \"racketeering investigator\" means any attorney or investigator so designated by the Attorney General and charged with the duty of enforcing or carrying into effect this chapter;"],[1,"(8) \"racketeering investigation\" means any inquiry conducted by any racketeering investigator for the purpose of ascertaining whether any person has been involved in any violation of this chapter or of any final order, judgment, or decree of any court of the United States, duly entered in any case or proceeding arising under this chapter;"],[1,"(9) \"documentary material\" includes any book, paper, document, record, recording, or other material; and"],[1,"(10) \"Attorney General\" includes the Attorney General of the United States, the Deputy Attorney General of the United States, the Associate Attorney General of the United States, any Assistant Attorney General of the United States, or any employee of the Department of Justice or any employee of any department or agency of the United States so designated by the Attorney General to carry out the powers conferred on the Attorney General by this chapter. Any department or agency so designated may use in investigations authorized by this chapter either the investigative provisions of this chapter or the investigative power of such department or agency otherwise conferred by law."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1961?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1961. Definitions","tname":"Crimes and Criminal Procedure","by":{"0":"15","1":"24, 24","2":"4"}},{"t":"usc","label":"21 U.S.C. § 802","url":"https://www.law.cornell.edu/uscode/text/21/802","subs":["(6)"],"stext":{"head":"§802. Definitions","paras":[[0,"As used in this subchapter:"],[0,"(1) The term \"addict\" means any individual who habitually uses any narcotic drug so as to endanger the public morals, health, safety, or welfare, or who is so far addicted to the use of narcotic drugs as to have lost the power of self-control with reference to his addiction."],[0,"(2) The term \"administer\" refers to the direct application of a controlled substance to the body of a patient or research subject by—"],[1,"(A) a practitioner (or, in his presence, by his authorized agent), or"],[1,"(B) the patient or research subject at the direction and in the presence of the practitioner,"],[0,"whether such application be by injection, inhalation, ingestion, or any other means."],[0,"(3) The term \"agent\" means an authorized person who acts on behalf of or at the direction of a manufacturer, distributor, or dispenser; except that such term does not include a common or contract carrier, public warehouseman, or employee of the carrier or warehouseman, when acting in the usual and lawful course of the carrier's or warehouseman's business."],[0,"(4) The term \"Drug Enforcement Administration\" means the Drug Enforcement Administration in the Department of Justice."],[0,"(5) The term \"control\" means to add a drug or other substance, or immediate precursor, to a schedule under part B of this subchapter, whether by transfer from another schedule or otherwise."],[0,"(6) The term \"controlled substance\" means a drug or other substance, or immediate precursor, included in schedule I, II, III, IV, or V of part B of this subchapter. The term does not include distilled spirits, wine, malt beverages, or tobacco, as those terms are defined or used in subtitle E of the Internal Revenue Code of 1986."],[0,"(7) The term \"counterfeit substance\" means a controlled substance which, or the container or labeling of which, without authorization, bears the trademark, trade name, or other identifying mark, imprint, number, or device, or any likeness thereof, of a manufacturer, distributor, or dispenser other than the person or persons who in fact manufactured, distributed, or dispensed such substance and which thereby falsely purports or is represented to be the product of, or to have been distributed by, such other manufacturer, distributor, or dispenser."],[0,"(8) The terms \"deliver\" or \"delivery\" mean the actual, constructive, or attempted transfer of a controlled substance or a listed chemical, whether or not there exists an agency relationship."],[0,"(9) The term \"depressant or stimulant substance\" means—"],[1,"(A) a drug which contains any quantity of barbituric acid or any of the salts of barbituric acid; or"],[1,"(B) a drug which contains any quantity of (i) amphetamine or any of its optical isomers; (ii) any salt of amphetamine or any salt of an optical isomer of amphetamine; or (iii) any substance which the Attorney General, after investigation, has found to be, and by regulation designated as, habit forming because of its stimulant effect on the central nervous system; or"],[1,"(C) lysergic acid diethylamide; or"],[1,"(D) any drug which contains any quantity of a substance which the Attorney General, after investigation, has found to have, and by regulation designated as having, a potential for abuse because of its depressant or stimulant effect on the central nervous system or its hallucinogenic effect."],[0,"(10) The term \"dispense\" means to deliver a controlled substance to an ultimate user or research subject by, or pursuant to the lawful order of, a practitioner, including the prescribing and administering of a controlled substance and the packaging, labeling or compounding necessary to prepare the substance for such delivery. The term \"dispenser\" means a practitioner who so delivers a controlled substance to an ultimate user or research subject."],[0,"(11) The term \"distribute\" means to deliver (other than by administering or dispensing) a controlled substance or a listed chemical. The term \"distributor\" means a person who so delivers a controlled substance or a listed chemical."],[0,"(12) The term \"drug\" has the meaning given that term by section 321(g)(1) of this title."],[0,"(13) The term \"felony\" means any Federal or State offense classified by applicable Federal or State law as a felony."],[0,"(14) The term \"isomer\" means the optical isomer, except as used in schedule I(c) and schedule II(a)(4). As used in schedule I(c), the term \"isomer\" means any optical, positional, or geometric isomer. As used in schedule II(a)(4), the term \"isomer\" means any optical or geometric isomer."],[0,"(15) The term \"manufacture\" means the production, preparation, propagation, compounding, or processing of a drug or other substance, either directly or indirectly or by extraction from substances of natural origin, or independently by means of chemical synthesis or by a combination of extraction and chemical synthesis, and includes any packaging or repackaging of such substance or labeling or relabeling of its container; except that such term does not include the preparation, compounding, packaging, or labeling of a drug or other substance in conformity with applicable State or local law by a practitioner as an incident to his administration or dispensing of such drug or substance in the course of his professional practice. The term \"manufacturer\" means a person who manufactures a drug or other substance."],[0,"(16)(A) Subject to subparagraph (B), the terms \"marihuana\" and \"marijuana\" mean all parts of the plant Cannabis sativa L., whether growing or not; the seeds thereof; the resin extracted from any part of such plant; and every compound, manufacture, salt, derivative, mixture, or preparation of such plant, its seeds or resin."],[0,"(B) The terms \"marihuana\" and \"marijuana\" do not include—"],[1,"(i) hemp, as defined in section 1639o of title 7; or"],[1,"(ii) the mature stalks of such plant, fiber produced from such stalks, oil or cake made from the seeds of such plant, any other compound, manufacture, salt, derivative, mixture, or preparation of such mature stalks (except the resin extracted therefrom), fiber, oil, or cake, or the sterilized seed of such plant which is incapable of germination."],[0,"(17) The term \"narcotic drug\" means any of the following whether produced directly or indirectly by extraction from substances of vegetable origin, or independently by means of chemical synthesis, or by a combination of extraction and chemical synthesis:"],[1,"(A) Opium, opiates, derivatives of opium and opiates, including their isomers, esters, ethers, salts, and salts of isomers, esters, and ethers, whenever the existence of such isomers, esters, ethers, and salts is possible within the specific chemical designation. Such term does not include the isoquinoline alkaloids of opium."],[1,"(B) Poppy straw and concentrate of poppy straw."],[1,"(C) Coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed."],[1,"(D) Cocaine, its salts, optical and geometric isomers, and salts of isomers."],[1,"(E) Ecgonine, its derivatives, their salts, isomers, and salts of isomers."],[1,"(F) Any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subparagraphs (A) through (E)."],[0,"(18) The term \"opiate\" or \"opioid\" means any drug or other substance having an addiction-forming or addiction-sustaining liability similar to morphine or being capable of conversion into a drug having such addiction-forming or addiction-sustaining liability."],[0,"(19) The term \"opium poppy\" means the plant of the species Papaver somniferum L., except the seed thereof."],[0,"(20) The term \"poppy straw\" means all parts, except the seeds, of the opium poppy, after mowing."],[0,"(21) The term \"practitioner\" means a physician, dentist, veterinarian, scientific investigator, pharmacy, hospital, or other person licensed, registered, or otherwise permitted, by the United States or the jurisdiction in which he practices or does research, to distribute, dispense, conduct research with respect to, administer, or use in teaching or chemical analysis, a controlled substance in the course of professional practice or research."],[0,"(22) The term \"production\" includes the manufacture, planting, cultivation, growing, or harvesting of a controlled substance."],[0,"(23) The term \"immediate precursor\" means a substance—"],[1,"(A) which the Attorney General has found to be and by regulation designated as being the principal compound used, or produced primarily for use, in the manufacture of a controlled substance;"],[1,"(B) which is an immediate chemical intermediary used or likely to be used in the manufacture of such controlled substance; and"],[1,"(C) the control of which is necessary to prevent, curtail, or limit the manufacture of such controlled substance."],[0,"(24) The term \"Secretary\", unless the context otherwise indicates, means the Secretary of Health and Human Services."],[0,"(25) The term \"serious bodily injury\" means bodily injury which involves—"],[1,"(A) a substantial risk of death;"],[1,"(B) protracted and obvious disfigurement; or"],[1,"(C) protracted loss or impairment of the function of a bodily member, organ, or mental faculty."],[0,"(26) The term \"State\" means a State of the United States, the District of Columbia, and any commonwealth, territory, or possession of the United States."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/802?type=usc&year=mostrecent&link-type=html"},"head":"§802. Definitions","tname":"Food and Drugs","by":{"0":"16","1":"7"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)","(a)(1)","(b)(1)(C)"],"stext":{"head":"§841. Prohibited acts A","paras":[[0,"(a) Unlawful acts"],[0,"Except as authorized by this subchapter, it shall be unlawful for any person knowingly or intentionally—"],[1,"(1) to manufacture, distribute, or dispense, or possess with intent to manufacture, distribute, or dispense, a controlled substance; or"],[1,"(2) to create, distribute, or dispense, or possess with intent to distribute or dispense, a counterfeit substance."],[0,"(b) Penalties"],[0,"Except as otherwise provided in section 849, 859, 860, or 861 of this title, any person who violates subsection (a) of this section shall be sentenced as follows:"],[0,"(1)(A) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 1 kilogram or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 5 kilograms or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 280 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 100 grams or more of phencyclidine (PCP) or 1 kilogram or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 10 grams or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 400 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 100 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 1000 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 1,000 or more marihuana plants regardless of weight; or"],[1,"(viii) 50 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 500 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 10 years or more than life and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $10,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment of not less than 15 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $20,000,000 if the defendant is an individual or $75,000,000 if the defendant is other than an individual, or both. If any person commits a violation of this subparagraph or of section 849, 859, 860, or 861 of this title after 2 or more prior convictions for a serious drug felony or serious violent felony have become final, such person shall be sentenced to a term of imprisonment of not less than 25 years and fined in accordance with the preceding sentence. Notwithstanding section 3583 of title 18, any sentence under this subparagraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 5 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 10 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(B) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 100 grams or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 500 grams or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 28 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 10 grams or more of phencyclidine (PCP) or 100 grams or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 1 gram or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 40 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 10 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 100 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 100 or more marihuana plants regardless of weight; or"],[1,"(viii) 5 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 50 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 5 years and not more than 40 years and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $5,000,000 if the defendant is an individual or $25,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment which may not be less than 10 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $8,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposed under this subparagraph shall, in the absence of such a prior conviction, include a term of supervised release of at least 4 years in addition to such term of imprisonment and shall, if there was such a prior conviction, include a term of supervised release of at least 8 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(C) In the case of a controlled substance in schedule I or II, gamma hydroxybutyric acid (including when scheduled as an approved drug product for purposes of section 3(a)(1)(B) of the Hillory J. Farias and Samantha Reid Date-Rape Drug Prohibition Act of 2000), or 1 gram of flunitrazepam, except as provided in subparagraphs (A), (B), and (D), such person shall be sentenced to a term of imprisonment of not more than 20 years and if death or serious bodily injury results from the use of such substance shall be sentenced to a term of imprisonment of not less than twenty years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $1,000,000 if the defendant is an individual or $5,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a felony drug offense has become final, such person shall be sentenced to a term of imprisonment of not more than 30 years and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $2,000,000 if the defendant is an individual or $10,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposing a term of imprisonment under this paragraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 3 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 6 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under the provisions of this subparagraph which provide for a mandatory term of imprisonment if death or serious bodily injury results, nor shall a person so sentenced be eligible for parole during the term of such a sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/841?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§841. Prohibited acts A","tname":"Food and Drugs","by":{"0":"10, 17, 21, 22","1":"2, 6, 2, 6"}},{"t":"usc","label":"21 U.S.C. § 959","url":"https://www.law.cornell.edu/uscode/text/21/959","subs":["(b)(1)"],"by":{"0":"10, 17"}},{"t":"usc","label":"46 U.S.C. § 70501","url":"https://www.law.cornell.edu/uscode/text/46/70501","by":{"0":"16"}},{"t":"usc","label":"46 U.S.C. § 70502","url":"https://www.law.cornell.edu/uscode/text/46/70502","by":{"0":"16"}},{"t":"usc","label":"46 U.S.C. § 70503","url":"https://www.law.cornell.edu/uscode/text/46/70503","by":{"0":"10, 16, 17"}},{"t":"usc","label":"46 U.S.C. § 70504","url":"https://www.law.cornell.edu/uscode/text/46/70504","by":{"0":"16"}},{"t":"usc","label":"46 U.S.C. § 70505","url":"https://www.law.cornell.edu/uscode/text/46/70505","by":{"0":"16"}},{"t":"usc","label":"46 U.S.C. § 70506","url":"https://www.law.cornell.edu/uscode/text/46/70506","by":{"0":"16"}},{"t":"usc","label":"46 U.S.C. § 70507","url":"https://www.law.cornell.edu/uscode/text/46/70507","by":{"0":"16"}},{"t":"usc","label":"46 U.S.C. § 70508","url":"https://www.law.cornell.edu/uscode/text/46/70508","by":{"0":"16"}},{"t":"usc","label":"21 U.S.C. § 801","url":"https://www.law.cornell.edu/uscode/text/21/801","by":{"0":"16, 24"}},{"t":"usc","label":"21 U.S.C. § 951","url":"https://www.law.cornell.edu/uscode/text/21/951","by":{"0":"16"}},{"t":"case","label":"Dean v. United States","cite":"556 U.S. 568","y":2009,"id":"2008/08-5274","sc":1,"op":1,"sum":"The Court held that 18 U.S.C. Section 924(c)(1)(A)(iii) does not require proof of intent to discharge a firearm in order to enhance a sentence.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Elonis v. United States","cite":"135 S. Ct. 2001","y":2015,"id":"2014/13-983","sc":1,"sum":"The Court found that in order to violate the transmission of threats provision, the threat requires both an objective and subjective intent.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Kawashima v. Holder","cite":"565 U.S. 478","y":2012,"id":"2011/10-577","sc":1,"op":3,"ar":2,"sum":"The Court held that filing a false tax return in violation of 26 U.S.C. Section 7206 qualifies as an aggravated felony under the Immigration and Nationality Act if the Government's revenue loss exceeds $10,000.","sumSrc":"Oyez","by":{"1":"9, 13, 14, 20, 22","2":"8, 10, 11"}},{"t":"case","label":"(III) Cases—Continued: Lockhart v. United States","cite":"136 S. Ct. 958","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/958/","sc":1,"ar":1,"by":{"1":"25, 26, 28, 29"}},{"t":"case","label":"Mathis v. United States","cite":"136 S. Ct. 2243","y":2016,"id":"2015/15-6092","sc":1,"op":3,"sum":"The Court determined that a state crime cannot qualify as a predicate offense under the Armed Career Criminal Act (ACCA) if the elements of the state offense are broader than those of a listed generic offense based on an “elements-only inquiry,” not a modified categorical approach.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"McNeill v. United States","cite":"563 U.S. 816","y":2011,"id":"2010/10-5258","sc":1,"sum":"The Court held that a federal sentencing court must determine whether an offense under state law is a \"serious drug offense\" within the meaning of the Armed Career Criminal Act by consulting the maximum sentence applicable at the time of the defendant's conviction.","sumSrc":"Oyez","by":{"1":"13, 16"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"sum":"The Court held 6-3 that under the harmless-error rule, which applies to a jury instruction that omits an element of an offense, the trial court's error did not render Neder's trial \"fundamentally unfair.\" Thus, the error was harmless.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Nijhawan v. Holder","cite":"557 U.S. 29","y":2009,"id":"2008/08-495","sc":1,"op":1,"sum":"The Court found that when an alien is convicted of conspiracy and held responsible for causing more than $10,000 in damages, the statute requirement used by the Immigration and Nationality Act (INA) to deport the alien is satisfied, even if the $10,000 is not established by a jury.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Scott v. State","cite":"808 So. 2d 166","y":2002,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%202d/808/166/","by":{"1":"27"}},{"t":"case","label":"State v. Adkins","cite":"96 So. 3d 412","y":2012,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%203d/96/412/","by":{"1":"7, 27"}},{"t":"case","label":"United States v. Alexander","cite":"331 F.3d 116","y":2003,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/331/116/","by":{"1":"18"}},{"t":"case","label":"United States v. Daniels","cite":"915 F.3d 148","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/915/148/","sum":"Concluding that offense under Pennsylvania law for manufacturing, delivering, or possessing with intent to manufacture a controlled substance satisfied Section 924(e)(2)(A)(ii) because Pennsylvania law’s definition of attempt liability sufficiently corresponded to federal definition.","sumSrc":"brief:1","by":{"1":"31"}},{"t":"case","label":"United States v. Franklin","cite":"904 F.3d 793","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/904/793/","op":1,"sum":"Concluding that Washington state offense for possession with intent to deliver cocaine did not satisfy Section 924(e)(2)(A)(ii) because court concluded that Washington law’s definition of accomplice liability was broader than “generic aiding and abetting liability”.","sumSrc":"brief:1","by":{"1":"31"}},{"t":"case","label":"United States v. Smith","cite":"775 F.3d 1262","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/775/1262/","op":1,"by":{"1":"8, 20","2":"13"}},{"t":"law","label":"Pub. L. No. 100-690","url":"https://www.govinfo.gov/link/statute/102/4312","by":{"1":"5"}},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"1":"5"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(43)(M)(i)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"1":"3"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)","(g)(1)"],"by":{"1":"3, 2, 6"}},{"t":"usc","label":"18 U.S.C. § 2252","url":"https://www.law.cornell.edu/uscode/text/18/2252","subs":["(b)(2)"],"by":{"1":"25"}},{"t":"usc","label":"21 U.S.C. § 812","url":"https://www.law.cornell.edu/uscode/text/21/812","subs":["(c)"],"by":{"1":"7"}},{"t":"case","label":"Lopez v. Gonzales","cite":"549 U.S. 47","y":2006,"id":"2006/05-547","sc":1,"sum":"The Court ruled 8-1 that a drug crime must be a felony under the federal Controlled Substances Act (CSA) in order to count as an aggravated felony for purposes of the INA. The opinion by Justice David Souter rejected as unnatural the government's interpretation of the term \"aggravated felony\" in the INA as encompassing any state-law felony punishable under the CSA, whether as a felony or not.","sumSrc":"Oyez","by":{"2":"9"}},{"t":"case","label":"Sanchez v. United States","cite":"940 F.3d 526","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/940/526/","by":{"2":"6"}},{"t":"case","label":"Sandoz Inc. v. Amgen Inc.","cite":"137 S. Ct. 1664","y":2017,"id":"2016/15-1039","sc":1,"sum":"The Court determined that the Biologics Price Competition and Innovation Act of 2009 allows for commercial notice of a “biosimilar product” to be effective if given prior to approval by the Food and Drug Administration (FDA), but that the Act’s notice requirement is not enforceable with an injunction.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"case","label":"Thomas v. State","cite":"522 P.2d 528","y":1974,"court":"Alaska","url":"https://www.courtlistener.com/c/P.2d/522/528/","by":{"2":"10"}},{"t":"case","label":"United States v. Jicarilla Apache Nation","cite":"564 U.S. 162","y":2011,"id":"2010/10-382","sc":1,"sum":"The Court held that the fiduciary exception to the attorney-client privilege does not apply to the general trust relationship between the United States and the Indian Tribes.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"United States v. Papia","cite":"560 F.2d 827","y":1977,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/560/827/","by":{"2":"11"}},{"t":"case","label":"United States v. Reid","cite":"861 F.3d 523","y":2017,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/861/523/","by":{"2":"6, 7"}},{"t":"case","label":"United States v. U.S. Gypsum Co.","cite":"438 U.S. 422","y":1978,"id":"1977/76-1560","sc":1,"sum":"Several major gypsum board manufacturers and various of their officials were indicted for violations of § 1 of the Sherman Act by allegedly engaging in a price-fixing conspiracy. One of the types of actions allegedly taken in formulating and effectuating the conspiracy was interseller price verification, i. e., the practice of telephoning a competing manufacturer to determine the price being currently offered on …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"10"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"rule","label":"Fed. R. Evid. 609","url":"https://www.law.cornell.edu/rules/fre/rule_609","subs":["(A)(2)"],"by":{"2":"12"}}]};